const DB_NAME = 'MartinLagunaDB';
const STORE_NAME = 'submissions';
const VERSION = 1;

export interface Submission {
  id?: number;
  name: string;
  email: string;
  phone: string;
  studentType: string;
  instrument: string;
  experience: string;
  message: string;
  timestamp: string;
}

export const initDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, VERSION);

    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: 'id', autoIncrement: true });
      }
    };

    request.onsuccess = (event) => {
      resolve((event.target as IDBOpenDBRequest).result);
    };

    request.onerror = (event) => {
      reject('IndexedDB error: ' + (event.target as IDBOpenDBRequest).error);
    };
  });
};

export const saveSubmission = async (submission: Omit<Submission, 'id'>): Promise<number> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(STORE_NAME, 'readwrite');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.add(submission);

    request.onsuccess = () => resolve(request.result as number);
    request.onerror = () => reject(request.error);
  });
};

export const getAllSubmissions = async (): Promise<Submission[]> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(STORE_NAME, 'readonly');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.getAll();

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

export const clearSubmissions = async (): Promise<void> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(STORE_NAME, 'readwrite');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.clear();

    request.onsuccess = () => resolve();
    request.onerror = () => reject(request.error);
  });
};

import React, { useEffect, useState } from 'react';
import { getAllSubmissions, clearSubmissions, Submission } from '../lib/db';

const AdminDashboard: React.FC = () => {
  const [submissions, setSubmissions] = useState<Submission[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchData = async () => {
    setLoading(true);
    try {
      const data = await getAllSubmissions();
      // Sort by latest first
      setSubmissions(data.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()));
    } catch (error) {
      console.error('Error fetching submissions:', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleClear = async () => {
    if (window.confirm('Are you sure you want to clear all submission data? This cannot be undone.')) {
      await clearSubmissions();
      setSubmissions([]);
    }
  };

  return (
    <div className="py-20 bg-[#FDFBF7] min-h-screen">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-12 gap-6">
          <div>
            <h1 className="text-5xl font-semibold mb-4 serif">Admin Dashboard</h1>
            <p className="text-[#666666]">Review and manage your website enquiries. Data is stored locally in your browser.</p>
          </div>
          <div className="flex gap-4">
            <button 
              onClick={fetchData}
              className="px-6 py-2 border border-[#4A5D4E] text-[#4A5D4E] rounded-sm hover:bg-[#F3F0EC] transition-colors text-sm font-medium"
            >
              Refresh Data
            </button>
            <button 
              onClick={handleClear}
              className="px-6 py-2 bg-red-600 text-white rounded-sm hover:bg-red-700 transition-colors text-sm font-medium"
            >
              Clear All Data
            </button>
          </div>
        </div>

        {loading ? (
          <div className="flex justify-center items-center h-64">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#4A5D4E]"></div>
          </div>
        ) : submissions.length === 0 ? (
          <div className="bg-white p-20 text-center rounded-sm border border-[#E8E4DE] shadow-sm">
            <p className="text-xl text-[#999999] serif italic">No enquiries found yet.</p>
          </div>
        ) : (
          <div className="bg-white rounded-sm border border-[#E8E4DE] shadow-sm overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-[#F3F0EC] border-b border-[#E8E4DE]">
                  <th className="px-6 py-4 text-xs font-bold uppercase tracking-wider text-[#666666]">Date</th>
                  <th className="px-6 py-4 text-xs font-bold uppercase tracking-wider text-[#666666]">Contact</th>
                  <th className="px-6 py-4 text-xs font-bold uppercase tracking-wider text-[#666666]">Details</th>
                  <th className="px-6 py-4 text-xs font-bold uppercase tracking-wider text-[#666666]">Experience & Message</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-[#E8E4DE]">
                {submissions.map((s) => (
                  <tr key={s.id} className="hover:bg-[#FDFBF7] transition-colors">
                    <td className="px-6 py-6 whitespace-nowrap align-top">
                      <div className="text-sm font-medium text-[#1A1A1A]">
                        {new Date(s.timestamp).toLocaleDateString()}
                      </div>
                      <div className="text-xs text-[#999999]">
                        {new Date(s.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      </div>
                    </td>
                    <td className="px-6 py-6 align-top">
                      <div className="text-sm font-bold text-[#1A1A1A]">{s.name}</div>
                      <div className="text-sm text-[#4A5D4E]">{s.email}</div>
                      <div className="text-xs text-[#999999]">{s.phone}</div>
                    </td>
                    <td className="px-6 py-6 align-top">
                      <div className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-[#4A5D4E]/10 text-[#4A5D4E] mb-1">
                        {s.instrument}
                      </div>
                      <div className="text-xs text-[#666666] italic capitalize">{s.studentType}</div>
                    </td>
                    <td className="px-6 py-6 align-top max-w-md">
                      <div className="text-xs font-bold text-[#666666] mb-1">Experience:</div>
                      <div className="text-sm text-[#333333] mb-3 leading-relaxed">{s.experience || 'N/A'}</div>
                      <div className="text-xs font-bold text-[#666666] mb-1">Message:</div>
                      <div className="text-sm text-[#666666] leading-relaxed italic">"{s.message || 'No additional message.'}"</div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
};

